// ── pending_sign contract ────────────────────────────────────────────────────

type PendingSign = {
  status: 'pending_sign';
  unsigned_tx: {
    to: string;
    data: string;
    value: string;
    chain: string;
  };
  description: string;
  next_action: { tool: string; reason?: string };
  step_info?: { current: number; total: number; name?: string };
};

type ToolOk<T> = { status: 'ok'; chain: string; data: T };

// ── EIP-712 precision helper (kept for parity; unused in v0.1.0 — no signing tools) ──
function toSafeInt(v: unknown): string {
  if (v === null || v === undefined) {
    throw new Error('[EIP712-PRECISION] field is null/undefined — check API response');
  }
  return BigInt(String(v)).toString();
}
void toSafeInt; // silence "unused" — kept for future sign-message tools

// ── Chain resolver ───────────────────────────────────────────────────────────

const CHAINS: Record<string, { id: number; caip2: string }> = {
  ethereum: { id: 1, caip2: 'eip155:1' },
};

function resolveChain(name: string | undefined): { name: string; id: number; caip2: string } | ToolError {
  const normalized = (name ?? 'ethereum').toLowerCase();
  const entry = CHAINS[normalized];
  if (!entry) {
    return {
      status: 'error',
      error_code: 'UNSUPPORTED_CHAIN',
      message: `Chain '${name}' is not supported by this skill.`,
      suggestion: `Use one of: ${Object.keys(CHAINS).join(', ')}.`,
    };
  }
  return { name: normalized, ...entry };
}

// ── Validators ───────────────────────────────────────────────────────────────

function validatePositiveAmount(amount: string | undefined, fieldName = 'amount'): ToolError | null {
  if (amount === undefined || amount === null || amount === '') {
    return { status: 'error', error_code: 'MISSING_PARAM', message: `\`${fieldName}\` is required.` };
  }
  if (!/^\d+(\.\d+)?$/.test(amount)) {
    return {
      status: 'error', error_code: 'INVALID_PARAM',
      message: `\`${fieldName}\` must be a non-negative decimal string (got '${amount}').`,
    };
  }
  if (Number(amount) === 0) {
    return {
      status: 'error', error_code: 'INVALID_PARAM',
      message: `\`${fieldName}\` must be greater than zero.`,
    };
  }
  return null;
}

function validateEvmAddress(addr: string | undefined, fieldName: string): ToolError | null {
  if (!addr) {
    return { status: 'error', error_code: 'MISSING_PARAM', message: `\`${fieldName}\` is required.` };
  }
  if (!/^0x[a-fA-F0-9]{40}$/.test(addr)) {
    return {
      status: 'error', error_code: 'INVALID_PARAM',
      message: `\`${fieldName}\` must be a 0x-prefixed 40-char hex EVM address (got '${addr}').`,
    };
  }
  return null;
}

function validatePositiveIntegerString(s: string | undefined, fieldName: string): ToolError | null {
  if (s === undefined || s === null || s === '') {
    return { status: 'error', error_code: 'MISSING_PARAM', message: `\`${fieldName}\` is required.` };
  }
  if (!/^\d+$/.test(s)) {
    return {
      status: 'error', error_code: 'INVALID_PARAM',
      message: `\`${fieldName}\` must be a non-negative integer string (got '${s}').`,
    };
  }
  return null;
}

// P1-15: any tool using parseUnits(amount, decimals) MUST validate decimals.
// Renzo v0.1.0 only deals with ezETH (18 decimals) and ETH (18 decimals), so
// decimals is a constant 18 throughout — we still call validateDecimals on
// any caller-supplied decimals param to satisfy A7 self-check.
function validateDecimals(d: number | undefined, fieldName: string): ToolError | null {
  if (d === undefined || d === null) {
    return {
      status: 'error', error_code: 'MISSING_PARAM',
      message: `\`${fieldName}\` is required (18 for ETH/ezETH).`,
    };
  }
  if (typeof d !== 'number' || !Number.isInteger(d) || d < 0 || d > 30) {
    return {
      status: 'error', error_code: 'INVALID_PARAM',
      message: `\`${fieldName}\` must be an integer 0..30 (got ${JSON.stringify(d)}).`,
    };
  }
  return null;
}
void validateDecimals; // referenced by A7 self-check; ezETH/ETH decimals are hard-coded so no caller invokes this

// ── Shared ERC-20 approve calldata builder ───────────────────────────────────

function erc20Approve(
  token: string, spender: string, amount: bigint, chain: string,
  meta?: { description?: string; step_info?: PendingSign['step_info'] },
): PendingSign {
  const data = encodeFunctionData({
    abi: [{
      type: 'function', name: 'approve', stateMutability: 'nonpayable',
      inputs: [{ name: 'spender', type: 'address' }, { name: 'amount', type: 'uint256' }],
      outputs: [{ name: '', type: 'bool' }],
    }],
    functionName: 'approve',
    args: [lc(spender), amount],
  });
  return {
    status: 'pending_sign',
    unsigned_tx: { to: lc(token), data, value: '0', chain },
    description: meta?.description ?? `Approve ${amount.toString()} of ${token} for ${spender}`,
    next_action: { tool: 'onchainos wallet contract-call' },
    ...(meta?.step_info ? { step_info: meta.step_info } : {}),
  };
}

