export async function getApr(_params: Record<string, never> = {}): Promise<ToolOk<{ apr: number; source: string }> | ToolError> {
  try {
    const { apr } = await renzoApi.getApr();
    return {
      status: 'ok',
      chain: 'ethereum',
      data: { apr, source: 'app.renzoprotocol.com/api/apr' },
    };
  } catch (e) {
    return {
      status: 'error',
      error_code: 'RENZO_API_ERROR',
      message: `Failed to fetch APR: ${(e as Error).message}`,
      suggestion: 'Retry; if persistent, the Renzo app API may be temporarily unavailable.',
    };
  }
}

export async function getProtocolStats(_params: Record<string, never> = {}): Promise<ToolOk<Record<string, unknown>> | ToolError> {
  try {
    const stats = await renzoApi.getStats();
    return { status: 'ok', chain: 'ethereum', data: stats };
  } catch (e) {
    return {
      status: 'error',
      error_code: 'RENZO_API_ERROR',
      message: `Failed to fetch protocol stats: ${(e as Error).message}`,
    };
  }
}

export async function getEzethRate(params: {
  source?: 'chain' | 'api';
  chain?: string;
} = {}): Promise<ToolOk<{ rate: string; source: 'chain' | 'api'; details?: Record<string, unknown> }> | ToolError> {
  const chainResult = resolveChain(params.chain);
  if ('status' in chainResult) return chainResult;
  const { name: chain } = chainResult;
  const source = params.source ?? 'chain';

  if (source === 'api') {
    try {
      const stats = await renzoApi.getStats();
      // Real /api/stats shape (verified 2026-05-12): data.restakedTVL.ezETH.price
      // — NOT data.ezETH.price. The vault details nest under restakedTVL.
      const restakedTVL = (stats.data as { restakedTVL?: { ezETH?: { price?: number; eth?: number; underlyingTotalSupply?: number } } }).restakedTVL;
      const ez = restakedTVL?.ezETH;
      if (!ez || typeof ez.price !== 'number') {
        return {
          status: 'error',
          error_code: 'RENZO_API_ERROR',
          message: 'ezETH price field missing from stats response (expected data.restakedTVL.ezETH.price).',
        };
      }
      return {
        status: 'ok',
        chain,
        data: {
          rate: String(ez.price),
          unit: 'USD per ezETH',
          source: 'api',
          details: { ethBackedEzeth: ez.eth, ezethTotalSupply: ez.underlyingTotalSupply },
        },
      };
    } catch (e) {
      return {
        status: 'error',
        error_code: 'RENZO_API_ERROR',
        message: `Failed to read API rate: ${(e as Error).message}`,
      };
    }
  }

  // source === 'chain'  → rate = totalTVLInETH / ezETH.totalSupply (both 1e18)
  try {
    const [tvl, supply] = await Promise.all([
      renzoChain.totalTVLInETH(chain),
      erc20.totalSupply(RENZO_ADDRESSES.ethereum.ezETH, chain),
    ]);
    if (supply === 0n) {
      return {
        status: 'error',
        error_code: 'RPC_ERROR',
        message: 'ezETH totalSupply read returned 0 — RPC anomaly.',
      };
    }
    // rate = tvl / supply, computed in fixed-point with 1e18 precision
    const rateScaled = (tvl * 10n ** 18n) / supply;
    return {
      status: 'ok',
      chain,
      data: {
        rate: formatUnits(rateScaled, 18),
        unit: 'ETH per ezETH',
        source: 'chain',
        details: {
          totalTVLInETH: formatUnits(tvl, 18),
          ezethTotalSupply: formatUnits(supply, 18),
        },
      },
    };
  } catch (e) {
    return {
      status: 'error',
      error_code: 'RPC_ERROR',
      message: `Failed to read on-chain rate: ${(e as Error).message}`,
    };
  }
}

export async function previewWithdraw(params: {
  amount: string;
  assetOut: string;
  chain?: string;
}): Promise<ToolOk<{ amount: string; assetOut: string; amountOutWei: string; amountOut: string; decimals: number }> | ToolError> {
  const chainResult = resolveChain(params.chain);
  if ('status' in chainResult) return chainResult;
  const { name: chain } = chainResult;

  const validationError =
    validatePositiveAmount(params.amount, 'amount') ??
    validateEvmAddress(params.assetOut, 'assetOut');
  if (validationError) return validationError;

  let amountWei: bigint;
  try {
    amountWei = parseUnits(params.amount, 18);
  } catch (e) {
    return { status: 'error', error_code: 'INVALID_PARAM', message: (e as Error).message };
  }

  try {
    const amountOutWei = await renzoChain.calculateAmountToRedeem(amountWei, params.assetOut, chain);
    // v0.1.0 assumes assetOut decimals = 18 (wETH / stETH). Callers using
    // assets with other decimals must adjust their own UI; see SKILL.md.
    const decimals = 18;
    return {
      status: 'ok',
      chain,
      data: {
        amount: params.amount,
        assetOut: lc(params.assetOut),
        amountOutWei: amountOutWei.toString(),
        amountOut: formatUnits(amountOutWei, decimals),
        decimals,
      },
    };
  } catch (e) {
    return {
      status: 'error',
      error_code: 'RPC_ERROR',
      message: `Failed to call calculateAmountToRedeem: ${(e as Error).message}`,
    };
  }
}

export async function listWithdrawRequests(params: {
  walletAddress: string;
  chain?: string;
}): Promise<ToolOk<{ indices: string[]; outstanding: string }> | ToolError> {
  const chainResult = resolveChain(params.chain);
  if ('status' in chainResult) return chainResult;
  const { name: chain } = chainResult;

  const validationError = validateEvmAddress(params.walletAddress, 'walletAddress');
  if (validationError) return validationError;

  // The deployed WithdrawQueue reverts on `withdrawRequests(address)` when the
  // user has zero entries (verified 2026-05-12 — Vitalik's address reverts even
  // though it cleanly returns 0 from getOutstandingWithdrawRequests). Guard by
  // probing outstanding first; only fetch indices if the user actually has any.
  let outstanding: bigint;
  try {
    outstanding = await renzoChain.getOutstandingWithdrawRequests(params.walletAddress, chain);
  } catch (e) {
    return {
      status: 'error',
      error_code: 'RPC_ERROR',
      message: `Failed to read outstanding withdrawal count: ${(e as Error).message}`,
    };
  }

  if (outstanding === 0n) {
    return {
      status: 'ok',
      chain,
      data: {
        indices: [],
        outstanding: '0',
      },
    };
  }

  try {
    const indices = await renzoChain.withdrawRequests(params.walletAddress, chain);
    return {
      status: 'ok',
      chain,
      data: {
        indices: indices.map(i => i.toString()),
        outstanding: outstanding.toString(),
      },
    };
  } catch (e) {
    return {
      status: 'error',
      error_code: 'RPC_ERROR',
      message: `Failed to read withdrawal request indices: ${(e as Error).message}`,
    };
  }
}

