export async function buildDepositEth(params: {
  amount: string;
  walletAddress?: string;
  chain?: string;
}): Promise<PendingSign | ToolError> {
  const chainResult = resolveChain(params.chain);
  if ('status' in chainResult) return chainResult;
  const { name: chain } = chainResult;

  const validationError = validatePositiveAmount(params.amount, 'amount');
  if (validationError) return validationError;

  let amountWei: bigint;
  try {
    amountWei = parseUnits(params.amount, 18);
  } catch (e) {
    return { status: 'error', error_code: 'INVALID_PARAM', message: (e as Error).message };
  }

  // Pre-broadcast gas + deposit-value balance gate (only fires in REAL mode + when wallet provided).
  if (params.walletAddress) {
    const addrErr = validateEvmAddress(params.walletAddress, 'walletAddress');
    if (addrErr) return addrErr;
    const err = await nativeBalanceCheck(params.walletAddress, amountWei, chain, 'ETH');
    if (err) return err;
  }

  const data = encodeFunctionData({
    abi: RESTAKE_MANAGER_ABI,
    functionName: 'depositETH',
    args: [],
  });

  return {
    status: 'pending_sign',
    unsigned_tx: {
      to: RENZO_ADDRESSES.ethereum.restakeManager,
      data,
      value: amountWei.toString(),
      chain,
    },
    description: `Deposit ${params.amount} ETH into Renzo RestakeManager and mint ezETH.`,
    next_action: { tool: 'onchainos wallet contract-call' },
  };
}

export async function buildRequestWithdraw(params: {
  amount: string;
  assetOut: string;
  walletAddress: string;
  chain?: string;
}): Promise<PendingSign | ToolError> {
  const chainResult = resolveChain(params.chain);
  if ('status' in chainResult) return chainResult;
  const { name: chain } = chainResult;

  const validationError =
    validatePositiveAmount(params.amount, 'amount') ??
    validateEvmAddress(params.assetOut, 'assetOut') ??
    validateEvmAddress(params.walletAddress, 'walletAddress');
  if (validationError) return validationError;

  let amountWei: bigint;
  try {
    amountWei = parseUnits(params.amount, 18);
  } catch (e) {
    return { status: 'error', error_code: 'INVALID_PARAM', message: (e as Error).message };
  }

  // Optional ezETH balance gate (helpful pre-broadcast diagnostic)
  try {
    const bal = await erc20.balanceOf(RENZO_ADDRESSES.ethereum.ezETH, params.walletAddress, chain);
    // Only enforce when reading real on-chain state (mock returns 0n unconditionally).
    if (process.env.RENZO_RUNTIME === 'real' && bal < amountWei) {
      return {
        status: 'error',
        error_code: 'INSUFFICIENT_BALANCE',
        message: `Wallet ezETH balance ${formatUnits(bal, 18)} < requested ${params.amount}.`,
        suggestion: 'Hold enough ezETH before queueing a withdrawal.',
      };
    }
  } catch (e) {
    return {
      status: 'error',
      error_code: 'RPC_ERROR',
      message: `Failed to read ezETH balance: ${(e as Error).message}`,
    };
  }

  // Step 1: allowance gate
  const currentAllowance = await erc20.allowance(
    RENZO_ADDRESSES.ethereum.ezETH,
    params.walletAddress,
    RENZO_ADDRESSES.ethereum.withdrawQueue,
    chain,
  );
  if (currentAllowance < amountWei) {
    return erc20Approve(
      RENZO_ADDRESSES.ethereum.ezETH,
      RENZO_ADDRESSES.ethereum.withdrawQueue,
      amountWei,
      chain,
      {
        description:
          `Approve ${params.amount} ezETH for Renzo WithdrawQueue. ` +
          `After this transaction lands, re-invoke buildRequestWithdraw with the same params ` +
          `to receive the withdraw transaction.`,
        step_info: { current: 1, total: 2, name: 'approve' },
      },
    );
  }

  // Step 2: withdraw
  const data = encodeFunctionData({
    abi: WITHDRAW_QUEUE_ABI,
    functionName: 'withdraw',
    args: [amountWei, lc(params.assetOut)],
  });

  return {
    status: 'pending_sign',
    unsigned_tx: {
      to: RENZO_ADDRESSES.ethereum.withdrawQueue,
      data,
      value: '0',
      chain,
    },
    description:
      `Queue withdrawal of ${params.amount} ezETH for ${params.assetOut}. ` +
      `Cooldown up to 15 days per Renzo's EigenLayer-backed unstake + buffer policy. ` +
      `Track via listWithdrawRequests and claim via buildClaimWithdraw once matured.`,
    next_action: { tool: 'onchainos wallet contract-call' },
    step_info: { current: 2, total: 2, name: 'withdraw' },
  };
}

export async function buildClaimWithdraw(params: {
  withdrawRequestIndex: string;
  walletAddress: string;
  chain?: string;
}): Promise<PendingSign | ToolError> {
  const chainResult = resolveChain(params.chain);
  if ('status' in chainResult) return chainResult;
  const { name: chain } = chainResult;

  const validationError =
    validatePositiveIntegerString(params.withdrawRequestIndex, 'withdrawRequestIndex') ??
    validateEvmAddress(params.walletAddress, 'walletAddress');
  if (validationError) return validationError;

  const data = encodeFunctionData({
    abi: WITHDRAW_QUEUE_ABI,
    functionName: 'claim',
    args: [BigInt(params.withdrawRequestIndex), lc(params.walletAddress)],
  });

  return {
    status: 'pending_sign',
    unsigned_tx: {
      to: RENZO_ADDRESSES.ethereum.withdrawQueue,
      data,
      value: '0',
      chain,
    },
    description:
      `Claim Renzo withdrawal request #${params.withdrawRequestIndex} for ${params.walletAddress}. ` +
      `Reverts on-chain if the request has not matured (EigenLayer 14d unstake + Renzo 3d buffer).`,
    next_action: { tool: 'onchainos wallet contract-call' },
  };
}
